using System;
using System.Collections.Generic;
using System.Linq;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Immutable.
    /// Corners are stored in order around the panel (0-1-2-3).
    /// </summary>
    public sealed class Panel
    {
        private readonly Point3d[] _corners;

        public Panel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index)
        {
            _corners = new[] { c0, c1, c2, c3 };
            Index = index;
            Area = ComputeArea(_corners);
            Deviation = ComputeDeviation(_corners);
        }

        /// <summary>The four corners in order around the panel.</summary>
        public IReadOnlyList<Point3d> Corners => _corners;

        /// <summary>Index of the panel in its grid.</summary>
        public int Index { get; }

        /// <summary>Area of the panel (sum of the two triangles 0-1-2 and 0-2-3).</summary>
        public double Area { get; }

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation { get; }

        /// <summary>Closed polyline through the four corners.</summary>
        public Polyline Outline => new Polyline(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });

        public PolylineCurve OutlineCurve => new PolylineCurve(Outline);

        public Point3d Center => new Point3d(
            _corners.Average(p => p.X),
            _corners.Average(p => p.Y),
            _corners.Average(p => p.Z));

        /// <summary>Length of edge i, running from corner i to corner i+1.</summary>
        public double EdgeLength(int i) => _corners[i % 4].DistanceTo(_corners[(i + 1) % 4]);

        public double[] EdgeLengths => new[] { EdgeLength(0), EdgeLength(1), EdgeLength(2), EdgeLength(3) };

        /// <summary>The two diagonals: corner 0 to 2 and corner 1 to 3.</summary>
        public double[] DiagonalLengths => new[] { _corners[0].DistanceTo(_corners[2]), _corners[1].DistanceTo(_corners[3]) };

        /// <summary>Bounding-rectangle width used for nesting and cut lists: mean of edges 0 and 2.</summary>
        public double NestWidth => 0.5 * (EdgeLength(0) + EdgeLength(2));

        /// <summary>Bounding-rectangle height used for nesting and cut lists: mean of edges 1 and 3.</summary>
        public double NestHeight => 0.5 * (EdgeLength(1) + EdgeLength(3));

        public bool IsValid => _corners.All(p => p.IsValid);

        public override string ToString() =>
            $"Panel {Index} (area {Area:0.###}, deviation {Deviation:0.###})";

        private static double ComputeArea(Point3d[] c)
        {
            double a = 0.5 * Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]).Length;
            double b = 0.5 * Vector3d.CrossProduct(c[2] - c[0], c[3] - c[0]).Length;
            return a + b;
        }

        private static double ComputeDeviation(Point3d[] c)
        {
            var plane = new Plane(c[0], c[1], c[2]);
            if (!plane.IsValid) return 0.0; // first three corners collinear: no defined plane
            return Math.Abs(plane.DistanceTo(c[3]));
        }
    }
}

