    /// <summary>Grasshopper wrapper so a <see cref="Panel"/> travels on a wire as one value.</summary>
    public class PanelGoo : GH_Goo<Panel>
    {
        public PanelGoo() { }
        public PanelGoo(Panel panel) : base(panel) { }

        public override bool IsValid => Value != null && Value.IsValid;
        public override string TypeName => "Panel";
        public override string TypeDescription => "A four-sided facade panel";

        public override IGH_Goo Duplicate() => new PanelGoo(Value); // Panel is immutable

        public override string ToString() => Value == null ? "Null panel" : Value.ToString();

        public override bool CastFrom(object source)
        {
            if (source is Panel p) { Value = p; return true; }
            if (source is PanelGoo g) { Value = g.Value; return true; }
            return false;
        }

        public override bool CastTo<Q>(ref Q target)
        {
            if (Value == null) return false;
            if (typeof(Q).IsAssignableFrom(typeof(Panel))) { target = (Q)(object)Value; return true; }
            if (typeof(Q).IsAssignableFrom(typeof(GH_Curve))) { target = (Q)(object)new GH_Curve(Value.OutlineCurve); return true; }
            if (typeof(Q).IsAssignableFrom(typeof(Curve))) { target = (Q)(object)Value.OutlineCurve; return true; }
            if (typeof(Q).IsAssignableFrom(typeof(GH_Integer))) { target = (Q)(object)new GH_Integer(Value.Index); return true; }
            return false;
        }

        public override bool Write(GH_IWriter writer)
        {
            if (Value == null) return true;
            writer.SetInt32("Index", Value.Index);
            for (int i = 0; i < 4; i++)
            {
                var p = Value.Corners[i];
                writer.SetDouble("X", i, p.X);
                writer.SetDouble("Y", i, p.Y);
                writer.SetDouble("Z", i, p.Z);
            }
            return true;
        }

        public override bool Read(GH_IReader reader)
        {
            if (!reader.ItemExists("Index")) { Value = null; return true; }
            var c = new Point3d[4];
            for (int i = 0; i < 4; i++)
                c[i] = new Point3d(reader.GetDouble("X", i), reader.GetDouble("Y", i), reader.GetDouble("Z", i));
            Value = new Panel(c[0], c[1], c[2], c[3], reader.GetInt32("Index"));
            return true;
        }
    }
}

