using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade
{
    /// <summary>A rectangle placed on a sheet, in sheet-local coordinates (origin at the sheet's lower-left corner).</summary>
    public readonly struct Placement
    {
        public Placement(int partIndex, int sheet, double x, double y, double width, double height, bool rotated)
        {
            PartIndex = partIndex; Sheet = sheet; X = x; Y = y; Width = width; Height = height; Rotated = rotated;
        }

        /// <summary>Index of the part in the input list.</summary>
        public int PartIndex { get; }
        public int Sheet { get; }
        public double X { get; }
        public double Y { get; }
        /// <summary>Placed width (after any rotation).</summary>
        public double Width { get; }
        /// <summary>Placed height (after any rotation).</summary>
        public double Height { get; }
        public bool Rotated { get; }
    }

    public sealed class NestResult
    {
        public List<Placement> Placements { get; } = new List<Placement>();
        public int SheetCount { get; set; }
        public int UnplacedCount { get; set; }
        public double Utilization { get; set; }
    }

    /// <summary>
    /// Shelf (next-fit) rectangle nesting: parts sorted tallest first, shelves filled left to right,
    /// a new shelf above when a part doesn't fit, a new sheet when a shelf doesn't fit, and parts
    /// turned 90 degrees when they only fit turned.
    /// </summary>
    public static class ShelfNester
    {
        public static NestResult Nest(
            IReadOnlyList<(double Width, double Height)> parts,
            double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancel = default,
            Action<double> progress = null)
        {
            var result = new NestResult();
            double maxX = sheetWidth - spacing;
            double maxY = sheetHeight - spacing;

            // Tallest first; stable on input order for ties.
            var order = Enumerable.Range(0, parts.Count)
                .OrderByDescending(i => parts[i].Height)
                .ToList();

            int sheet = -1;          // current sheet (-1 = none opened yet)
            double shelfY = 0;       // bottom of current shelf
            double shelfHeight = 0;  // tallest part on current shelf
            double cursorX = 0;      // next free x on current shelf
            double placedArea = 0;

            for (int n = 0; n < order.Count; n++)
            {
                cancel.ThrowIfCancellationRequested();
                int idx = order[n];
                double w = parts[idx].Width, h = parts[idx].Height;

                bool fitsUpright = spacing + w <= maxX && spacing + h <= maxY && w > 0 && h > 0;
                bool fitsTurned = spacing + h <= maxX && spacing + w <= maxY && w > 0 && h > 0;
                if (!fitsUpright && !fitsTurned)
                {
                    result.UnplacedCount++;
                    progress?.Invoke((n + 1.0) / order.Count);
                    continue;
                }

                bool placed = false;
                if (sheet >= 0)
                {
                    // 1) Current shelf.
                    placed = TryPlace(cursorX, shelfY, w, h, maxX, maxY, out bool rot, out double pw, out double ph);
                    if (placed)
                    {
                        Commit(ref cursorX, ref shelfHeight, pw, ph, spacing);
                        result.Placements.Add(new Placement(idx, sheet, cursorX - pw - spacing, shelfY, pw, ph, rot));
                    }
                    else
