    {
        public static NestResult Nest(
            IReadOnlyList<(double Width, double Height)> parts,
            double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancel = default,
            Action<double> progress = null)
        {
            var result = new NestResult();
            double maxX = sheetWidth - spacing;
            double maxY = sheetHeight - spacing;

