                    Commit(ref cursorX, ref shelfHeight, pw, ph, spacing);
                    result.Placements.Add(new Placement(idx, sheet, spacing, shelfY, pw, ph, rot));
                }

                placedArea += w * h;
                progress?.Invoke((n + 1.0) / order.Count);
            }

            result.SheetCount = sheet + 1;
            double sheetArea = sheetWidth * sheetHeight;
            result.Utilization = result.SheetCount > 0 && sheetArea > 0
                ? placedArea / (result.SheetCount * sheetArea)
                : 0.0;
            return result;
        }

        private static bool TryPlace(double x, double y, double w, double h, double maxX, double maxY,
            out bool rotated, out double placedW, out double placedH)
        {
            if (x + w <= maxX && y + h <= maxY) { rotated = false; placedW = w; placedH = h; return true; }
            if (x + h <= maxX && y + w <= maxY) { rotated = true; placedW = h; placedH = w; return true; }
