namespace BenchPlugin.Facade.Components
{
    public class PanelInfoComponent : GH_Component
    {
        public PanelInfoComponent()
            : base("Panel Info", "PInfo", "Deconstructs a panel", "Facade", "Panels")
        {
        }

        public override Guid ComponentGuid => new Guid("3b8d1f27-6c4e-4a90-b2d5-7e1a9c3f5b62");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panel", "P", "Panel to deconstruct", GH_ParamAccess.item);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddPointParameter("Corners", "C", "The four corners, in order around the panel", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outline", "O", "Closed panel outline", GH_ParamAccess.item);
            pManager.AddNumberParameter("Area", "A", "Panel area", GH_ParamAccess.item);
            pManager.AddPointParameter("Center", "Ce", "Average of the four corners", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Index", "I", "Index of the panel in its grid", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            PanelGoo goo = null;
            if (!DA.GetData(0, ref goo) || goo?.Value == null) return;
            var panel = goo.Value;

            DA.SetDataList(0, panel.Corners);
            DA.SetData(1, panel.OutlineCurve);
            DA.SetData(2, panel.Area);
            DA.SetData(3, panel.Center);
            DA.SetData(4, panel.Index);
        }
    }
}

