        public override Guid ComponentGuid => new Guid("2c6a8f41-9b3e-4d75-a0c8-6e4f1b7d3a59");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            PanelData.AddPanelsInput(pManager, "Panels to group");
            pManager.AddNumberParameter("Tolerance", "T", "Maximum difference per sorted edge or diagonal length", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel, numbered in order of first appearance from 0", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParameter(), "Representatives", "R", "The first panel of each group", GH_ParamAccess.list);
        }

        /// <summary>Sorted edges (4 values) followed by sorted diagonals (2 values).</summary>
        private static double[] Signature(Panel p)
        {
            var edges = p.EdgeLengths.OrderBy(x => x);
            var diagonals = p.DiagonalLengths.OrderBy(x => x);
            return edges.Concat(diagonals).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelData.GetPanels(DA, 0);
            double tolerance = 1.0;
            DA.GetData(1, ref tolerance);

            var groups = new List<int>(panels.Count);
            var repSignatures = new List<double[]>();
            var representatives = new List<Panel>();

            foreach (var panel in panels)
            {
                var sig = Signature(panel);
                int group = repSignatures.FindIndex(r => Matches(r, sig, tolerance));
                if (group < 0)
                {
                    group = repSignatures.Count;
                    repSignatures.Add(sig);
                    representatives.Add(panel);
                }
                groups.Add(group);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, representatives.Count);
            DA.SetDataList(2, PanelData.Wrap(representatives));
        }
    }
}

