        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            // Tree access so the whole facade is nested in a single run regardless of data structure.
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels to nest", GH_ParamAccess.tree);
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Placed panel rectangles; sheets side by side along X, Sheet Width + 100 apart", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "Sh", "Sheet index of each placed panel (same order as Outlines)", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed rectangle area / (Sheet Count x sheet area)", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            if (!DA.GetDataTree(0, out GH_Structure<PanelGoo> tree)) tree = new GH_Structure<PanelGoo>();
            double width = 3000.0, height = 1500.0, spacing = 10.0;
            DA.GetData(1, ref width);
            DA.GetData(2, ref height);
            DA.GetData(3, ref spacing);

            // Deliver a finished run, if this solution was triggered by its completion.
            var done = _completed;
            _completed = null;
            if (done != null && done.RunId == _runId)
            {
                if (done.Error != null)
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Nesting failed: " + done.Error);
                    Message = "Failed";
                    return;
                }
                Output(DA, done.Result, width);
                return;
            }

            // Inputs changed (or first run): stop the old run and start a new one.
            CancelRun();

            if (width <= 0 || height <= 0 || spacing < 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Sheet Width and Sheet Height must be positive and Spacing must not be negative.");
                Message = null;
                return;
            }

            var parts = tree.AllData(true)
                .OfType<PanelGoo>()
                .Where(g => g.Value != null)
                .Select(g => (g.Value.NestWidth, g.Value.NestHeight))
                .ToList();

            var cts = new CancellationTokenSource();
            _cts = cts;
            int runId = ++_runId;
            _lastPercent = -1;
            Message = "Nesting 0%";
            AddRuntimeMessage(GH_RuntimeMessageLevel.Remark, $"Nesting {parts.Count} panels in the background...");

            Task.Run(() =>
            {
                var completed = new Completed { RunId = runId };
                try
                {
                    completed.Result = ShelfNester.Nest(parts, width, height, spacing, cts.Token,
                        fraction => ReportProgress(runId, cts.Token, fraction));
                }
                catch (OperationCanceledException)
                {
                    return;
                }
                catch (Exception ex)
                {
                    completed.Error = ex.Message;
                }

                if (cts.IsCancellationRequested) return;
                Rhino.RhinoApp.InvokeOnUiThread((Action)(() =>
                {
                    if (runId != _runId || cts.IsCancellationRequested) return;
                    _completed = completed;
                    ExpireSolution(true);
                }));
            }, cts.Token);
        }

        private void Output(IGH_DataAccess DA, NestResult result, double sheetWidth)
        {
            var outlines = new List<Curve>(result.Placements.Count);
            var sheets = new List<int>(result.Placements.Count);
            foreach (var p in result.Placements)
            {
                double x0 = p.Sheet * (sheetWidth + SheetGap) + p.X;
                var rect = new Rectangle3d(Plane.WorldXY, new Point3d(x0, p.Y, 0), new Point3d(x0 + p.Width, p.Y + p.Height, 0));
                outlines.Add(rect.ToPolyline().ToPolylineCurve());
                sheets.Add(p.Sheet);
            }

            if (result.UnplacedCount > 0)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{result.UnplacedCount} panel(s) fit on no sheet and were not nested.");

            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, result.SheetCount);
            DA.SetData(3, result.Utilization);
            Message = $"{result.SheetCount} sheet(s)";
        }

        private void ReportProgress(int runId, CancellationToken token, double fraction)
        {
            int percent = (int)(fraction * 100);
            if (percent == _lastPercent) return; // throttle UI updates to whole percents
            _lastPercent = percent;
            Rhino.RhinoApp.InvokeOnUiThread((Action)(() =>
            {
                if (runId != _runId || token.IsCancellationRequested) return;
                Message = $"Nesting {percent}%";
                OnDisplayExpired(true);
            }));
        }

        private void CancelRun()
        {
            if (_cts == null) return;
            _cts.Cancel();
            _cts = null;
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            CancelRun();
            _runId++;
            base.RemovedFromDocument(document);
        }

        public override void DocumentContextChanged(GH_Document document, GH_DocumentContext context)
        {
            if (context == GH_DocumentContext.Close || context == GH_DocumentContext.Unloaded)
            {
                CancelRun();
                _runId++;
            }
            base.DocumentContextChanged(document, context);
        }
    }
}

