        {
            int i = pManager.AddParameter(new PanelParameter(), "Panels", "P", description, GH_ParamAccess.list);
            pManager[i].Optional = optional;
        }

        /// <summary>Reads a list of panels, dropping nulls. Returns an empty list when nothing is connected.</summary>
        public static List<Panel> GetPanels(IGH_DataAccess DA, int index)
        {
            var goo = new List<PanelGoo>();
            DA.GetDataList(index, goo);
            return goo.Where(g => g != null && g.Value != null).Select(g => g.Value).ToList();
        }

        public static IEnumerable<PanelGoo> Wrap(IEnumerable<Panel> panels) => panels.Select(p => new PanelGoo(p));
    }
}

