using System;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class PlanarityComponent : GH_Component
    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Checks how far each panel is from flat", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("9c4e2a83-5d1b-4f7c-8e36-1a2b7d9f4c05");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            PanelData.AddPanelsInput(pManager, "Panels to check");
            pManager.AddNumberParameter("Tolerance", "T", "Maximum deviation for a panel to count as flat", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Distance from the fourth corner to the plane through the other three", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "True when Deviation is at most Tolerance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelData.GetPanels(DA, 0);
            double tolerance = 0.5;
            DA.GetData(1, ref tolerance);

            var deviation = panels.Select(p => p.Deviation).ToList();
            var flat = deviation.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;

            if (notFlat * 2 > panels.Count)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{notFlat} of {panels.Count} panels are not flat (deviation above {tolerance}).");

            DA.SetDataList(0, deviation);
            DA.SetDataList(1, flat);
            DA.SetData(2, flatCount);
        }
    }
}

using System;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class ClassifyPanelsComponent : GH_Component
    {
        public const string Flat = "flat";
        public const string ColdBent = "cold-bent";
        public const string Custom = "custom";

        public ClassifyPanelsComponent()
            : base("Classify Panels", "Classify", "Classifies panels as flat, cold-bent or custom by planarity deviation", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("5a1f7c39-2e8d-4b6a-9f04-8c3d1e5b7a26");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            PanelData.AddPanelsInput(pManager, "Panels to classify");
            pManager.AddNumberParameter("Tolerance", "T", "Flat tolerance; cold-bent up to 10 times this", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("Type", "T", "\"flat\", \"cold-bent\" or \"custom\", one per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "F", "Number of flat panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Cold Bent Count", "B", "Number of cold-bent panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Custom Count", "C", "Number of custom panels", GH_ParamAccess.item);
        }

        public static string Classify(double deviation, double tolerance)
        {
            if (deviation <= tolerance) return Flat;
            if (deviation <= 10.0 * tolerance) return ColdBent;
            return Custom;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelData.GetPanels(DA, 0);
            double tolerance = 0.5;
            DA.GetData(1, ref tolerance);

            var types = panels.Select(p => Classify(p.Deviation, tolerance)).ToList();

            DA.SetDataList(0, types);
            DA.SetData(1, types.Count(t => t == Flat));
            DA.SetData(2, types.Count(t => t == ColdBent));
            DA.SetData(3, types.Count(t => t == Custom));
        }
    }
}

