namespace BenchPlugin.Facade.Components
{
    public class PanelStatsComponent : GH_Component
    {
        public PanelStatsComponent()
            : base("Panel Stats", "Stats", "Area statistics for a set of panels", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("7d3b9e15-4a2c-4c8f-b6e1-0f5a3d8c2b97");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            // Optional so an empty input reaches SolveInstance and gets the error below.
            PanelData.AddPanelsInput(pManager, "Panels to measure", optional: true);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "T", "Sum of panel areas", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Mean", "Mean panel area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelData.GetPanels(DA, 0);
            if (panels.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "There are no panels.");
                return;
            }

            var areas = panels.Select(p => p.Area).ToList();
            DA.SetData(0, areas.Sum());
            DA.SetData(1, areas.Min());
            DA.SetData(2, areas.Max());
            DA.SetData(3, areas.Average());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Groups panels with matching edge and diagonal lengths", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("2c6a8f41-9b3e-4d75-a0c8-6e4f1b7d3a59");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            PanelData.AddPanelsInput(pManager, "Panels to group");
            pManager.AddNumberParameter("Tolerance", "T", "Maximum difference per sorted edge or diagonal length", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel, numbered in order of first appearance from 0", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParameter(), "Representatives", "R", "The first panel of each group", GH_ParamAccess.list);
        }

        /// <summary>Sorted edges (4 values) followed by sorted diagonals (2 values).</summary>
        private static double[] Signature(Panel p)
        {
            var edges = p.EdgeLengths.OrderBy(x => x);
            var diagonals = p.DiagonalLengths.OrderBy(x => x);
            return edges.Concat(diagonals).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelData.GetPanels(DA, 0);
            double tolerance = 1.0;
            DA.GetData(1, ref tolerance);

            var groups = new List<int>(panels.Count);
            var repSignatures = new List<double[]>();
            var representatives = new List<Panel>();

            foreach (var panel in panels)
            {
                var sig = Signature(panel);
                int group = repSignatures.FindIndex(r => Matches(r, sig, tolerance));
                if (group < 0)
                {
                    group = repSignatures.Count;
                    repSignatures.Add(sig);
                    representatives.Add(panel);
                }
                groups.Add(group);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, representatives.Count);
            DA.SetDataList(2, PanelData.Wrap(representatives));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class CutListComponent : GH_Component
    {
        public CutListComponent()
            : base("Cut List", "CutList", "Builds a CSV cut list and optionally writes it to a file", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("8e5c2d73-1f4a-4b9e-9d62-3a7b0c5e1f84");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            PanelData.AddPanelsInput(pManager, "Panels to list");
            int path = pManager.AddTextParameter("Path", "Path", "File to write the CSV to", GH_ParamAccess.item, string.Empty);
            pManager[path].Optional = true;
            pManager.AddBooleanParameter("Write", "W", "Write the CSV to Path", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list: index, width, height, area, deviation", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "Ok", "True when the file was written", GH_ParamAccess.item);
        }

        public static string BuildCsv(IEnumerable<Panel> panels)
        {
            var ci = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.Append("index,width,height,area,deviation\n");
            foreach (var p in panels)
            {
                sb.Append(p.Index.ToString(ci)).Append(',')
                  .Append(p.NestWidth.ToString("R", ci)).Append(',')
                  .Append(p.NestHeight.ToString("R", ci)).Append(',')
                  .Append(p.Area.ToString("R", ci)).Append(',')
                  .Append(p.Deviation.ToString("R", ci)).Append('\n');
            }
            return sb.ToString();
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelData.GetPanels(DA, 0);
            string path = string.Empty;
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            string csv = BuildCsv(panels);
            DA.SetData(0, csv);

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                }
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, $"Could not write '{path}': {ex.Message}");
                    }
                }
            }
            DA.SetData(1, written);
        }
    }
}
